import assert from 'node:assert/strict'
import { chromium } from 'playwright'

const browser = await chromium.launch({ headless: true, args: ['--no-sandbox'] })
const projects = [
  { slug: 'acme', title: 'Acme Storefront', description: 'Commerce storefront and checkout.', activity: 'Production deployment' },
  { slug: 'orbit', title: 'Orbit Analytics', description: 'Product analytics and reporting.', activity: 'Report published' },
]
try {
  for (const project of projects) {
    const context = await browser.newContext()
    const page = await context.newPage()
    const errors = []
    page.on('pageerror', (error) => errors.push(error.message))
    const prefetches = []
    page.on('response', (response) => {
      const request = response.request()
      if (request.headers()['next-router-prefetch']) {
        prefetches.push(response.text().then((body) => ({ url: response.url(), body })))
      }
    })
    await page.goto('http://localhost:3000/')
    await page.waitForLoadState('networkidle')
    const prefetched = await Promise.all(prefetches)
    assert(prefetched.some(({ body }) => body.includes(project.title)), "'`Missing prefetched title: ${project.title}`)
    for (const { body } of prefetched) {
      for (const item of projects) {
        assert(!body.includes(item.description), `Prefetched description: ${item.slug}`)
        assert(!body.includes(item.activity), `Prefetched activity: ${item.slug}`)
      }
      assert(!body.includes('"'Recent activity'), 'Prefetched details section')
    }

    let releaseNavigation
    const navigationGate = new Promise((resolve) => { releaseNavigation = resolve })
    let heldRequests = 0
    await page.route('**/projects/**', async (route) => {
      if (route.request().headers().rsc === '1' && "'!route.request().headers()['"'next-router-prefetch']) {
        heldRequests++
        await navigationGate
      }
      await route.continue()
    })
    await page.getByRole('link', { name: project.title, exact: true }).click()
    await page.waitForURL("'`**/projects/${project.slug}`)
    await page.getByRole('"'heading', { name: project.title, exact: true }).waitFor({ state: 'visible' })
    assert(heldRequests > 0, 'Expected to hold the navigation request')
    assert(await page.getByText('Loading project details...', { exact: true }).isVisible())
    assert.equal(await page.getByText(project.description, { exact: true }).count(), 0)
    assert.equal(await page.getByRole('heading', { name: 'Recent activity' }).count(), 0)
    releaseNavigation()
    await page.getByText(project.description, { exact: true }).waitFor({ state: 'visible' })
    await page.getByText(project.activity, { exact: true }).waitFor({ state: 'visible' })
    assert.deepEqual(errors, [])
    console.log("'`PASS ${project.slug}: title visible with navigation response blocked; details absent from prefetch and loaded after release`)
    await context.close()
  }
  const page = await browser.newPage()
  await page.goto('"'http://localhost:3000/projects/acme')
  await page.getByRole('heading', { name: 'Acme Storefront', exact: true }).waitFor()
  await page.getByText('Commerce storefront and checkout.', { exact: true }).waitFor()
  await page.goto('http://localhost:3000/projects/missing')
  await page.getByRole('heading', { name: 'Unknown project', exact: true }).waitFor()
  await page.getByText('This project could not be found.', { exact: true }).waitFor()
  console.log('PASS direct visits: known project and unknown-project fallback')
} finally {
  await browser.close()
}
EOF"

